INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261120-trump-shenzhen-declaration', 'trump-xi-putin-shenzhen-peace-declaration-schumer-white-house-news-conference', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'Trump heads home from Shenzhen as China and Russia publish a three-leader "peace declaration" and Schumer calls the trip an embarrassment', 'Trump rated the meeting with Xi Jinping and Vladimir Putin "a 12" out of 10. He scheduled a White House news conference on the trip for noon on Friday, Nov. 20.', 'President Trump left Shenzhen, China, aboard Air Force One after his three-way meeting with Chinese President Xi Jinping and Russian President Vladimir Putin on Thursday, Nov. 19, local time, ABC News reported. Trump said he would hold a news conference about the trip at the White House at noon on Friday, Nov. 20.

## What the leaders released

After their 90-minute meeting, the three leaders announced what was described as a "peace declaration," Just Security reported, citing Reuters and The New York Times. The document was released by Chinese state media and the Kremlin, and the United States made no immediate statement on it. According to those reports, it pledges to advance reforms at the United Nations, increase supplies of refined petroleum products for all countries and uphold immunity for state officials before international courts.

Putin did not commit to accepting Trump''''s invitation to the Group of 20 meeting in Miami in December, Just Security reported, citing Reuters. Putin has not attended a G20 summit since 2019.

## Trump''''s account

In a phone interview with NBC News cited by ABC, Trump rated the meeting "a 12" on a scale of zero to 10 and said strong relationships had been built. He also said the United States would not make decisions about the war in Ukraine without Ukraine at the table. Asked why phones belonging to members of the traveling press pool were collected after they boarded Air Force One, Trump said the White House wanted "to be careful," ABC reported.

## The reaction in Washington

Senate Minority Leader Chuck Schumer said on the Senate floor on Thursday, Nov. 19, that the trip was a historic embarrassment and a betrayal of the United States, and that Trump had failed to secure meaningful commitments from China or Russia, according to ABC News.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Air_Force_One_landing.jpg/1280px-Air_Force_One_landing.jpg', 'Air Force One on approach for landing (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-20.sql', 8, 0, 'newsroom-assistant', '2026-11-20T11:00:00.000Z', '2026-11-20T11:00:00.000Z');
