INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261120-jeffries-speaker-nominee', 'house-democrats-nominate-hakeem-jeffries-speaker-katherine-clark-majority-leader', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'House Democrats nominate Hakeem Jeffries for speaker 251-11 and pick Massachusetts Rep. Katherine Clark as majority leader', 'Jeffries is in line to become the first Black speaker when the new Congress meets in January. Eleven Democrats voted no in the closed-door caucus vote on Wednesday, Nov. 18.', 'House Democrats voted 251-11 on Wednesday, Nov. 18, to nominate Rep. Hakeem Jeffries of New York for speaker, Roll Call and CBS News reported. Jeffries, who had no announced opponent, asked for a recorded vote in the closed-door caucus meeting. With Democrats on track to hold more than 250 seats in the next Congress, he is expected to clear the 218 votes needed on the House floor and become the first Black speaker.

## A Massachusetts first

The caucus chose Rep. Katherine Clark of Massachusetts as majority leader, making her the first woman to hold that post, according to both reports. Rep. Pete Aguilar of California was elected whip, the first Latino in that role. Rep. Ted Lieu of California was elected caucus chair, and CBS reported that Rep. Joe Neguse of Colorado will be assistant speaker.

## The dissent

Roll Call counted 11 defections. Seven of the 11 released a joint statement saying talks with leadership were ongoing and had made meaningful progress, and listing demands that included Medicare for All, stopping what they called ICE terror and getting money out of politics, Roll Call reported. CBS named six who voted no, including Claire Valdez and Darializa Avila Chevalier of New York.

Jeffries told colleagues the party''''s job was to fight what he called MAGA extremism, not each other, according to Roll Call. The floor vote for speaker will take place when the new Congress convenes, beginning on Jan. 3.

Senate Democrats face their own leadership contest, with Sen. Chris Van Hollen of Maryland challenging Schumer. CBS reported that Schumer expects that vote early in December.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Rep-Hakeem-Jeffries-Official-Portrait.jpg/1280px-Rep-Hakeem-Jeffries-Official-Portrait.jpg', 'Rep. Hakeem Jeffries, D-N.Y. (file). Official U.S. House portrait via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-20.sql', 8, 0, 'newsroom-assistant', '2026-11-20T11:00:00.000Z', '2026-11-20T11:00:00.000Z');
