INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261120-trump-nyt-suit-proceeds', 'judge-merryday-trump-defamation-suit-new-york-times-penguin-random-house-proceeds', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Judge lets Trump''s defamation suit against The New York Times and Penguin Random House move forward', 'U.S. District Judge Steven Merryday in Tampa dismissed two claims on Thursday, Nov. 19, but found the rest of the complaint plausible. The case concerns a book by Peter Baker and articles by Susanne Craig and Russ Buettner.', 'A federal judge in Tampa, Florida, ruled on Thursday, Nov. 19, that President Trump''''s defamation lawsuit against The New York Times and the publisher Penguin Random House may proceed, Reuters reported.

## What the judge decided

U.S. District Judge Steven Merryday, an appointee of President George H.W. Bush, threw out two of Trump''''s claims, according to Reuters. He found that the rest of the complaint plausibly alleged that statements accusing Trump of planning and carrying out complex crimes were based on incomplete and minimal information. The reports did not identify which two claims were dismissed.

## What the suit targets

The lawsuit cites 22 statements in a book by Times journalist Peter Baker and 12 statements in articles by Susanne Craig and Russ Buettner, Reuters reported. The material covers Trump''''s role in creating "The Apprentice," his inheritance from his father, his business ventures and his upbringing in New York City. Trump calls the coverage false and malicious and says it was meant to sabotage his 2024 campaign.

The Times and Penguin Random House deny defaming Trump. In seeking dismissal, they argued that the complaint did not explain how the statements were defamatory and that it relied on opinions that cannot be proven true or false, according to Reuters. Representatives for the defendants and Trump''''s lawyers did not immediately respond to requests for comment.

## Other media suits

Al Jazeera, carrying the Reuters report, noted that a judge had allowed Trump''''s $10 billion suit against the BBC to proceed days earlier, and that Trump refiled a $10 billion suit against The Wall Street Journal in May.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/New_York_Times_Building.jpg/1280px-New_York_Times_Building.jpg', 'The New York Times Building in Manhattan (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-20.sql', 7, 0, 'newsroom-assistant', '2026-11-20T11:00:00.000Z', '2026-11-20T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261120-trump-nyt-suit-proceeds-src1', 'bd-20261120-trump-nyt-suit-proceeds', 'Trump''s defamation case against New York Times and Penguin Random House may proceed, judge rules', 'https://www.yahoo.com/news/us/articles/trumps-defamation-case-against-york-174418079.html', 'Reuters (via Yahoo News)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-20T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-20. Editor to confirm.', 'newsroom-assistant', '2026-11-20T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261120-trump-nyt-suit-proceeds-src2', 'bd-20261120-trump-nyt-suit-proceeds', 'Trump''s case against NYT and Penguin Random House may proceed: Judge', 'https://www.aljazeera.com/economy/2026/11/19/trumps-case-against-nyt-and-penguin-random-house-may-proceed-judge', 'Al Jazeera (Reuters)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-20T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-20. Editor to confirm.', 'newsroom-assistant', '2026-11-20T11:00:00.000Z');
INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261120-trump-nyt-suit-proceeds-ev1', 'bd-20261120-trump-nyt-suit-proceeds', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-20T11:00:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261120-dc-circuit-transgender-troops', 'dc-circuit-denies-stay-pentagon-transgender-troops-27-plaintiffs-supreme-court-dec-4', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Divided appeals court bars the Pentagon from discharging 27 transgender service members who sued', 'A 2-1 D.C. Circuit order on Tuesday, Nov. 17, covers only the currently serving plaintiffs. The Supreme Court is set to consider whether to take the case at its Dec. 4 conference.', 'A divided panel of the U.S. Court of Appeals for the D.C. Circuit on Tuesday, Nov. 17, refused the Trump administration''''s request to keep enforcing its ban on transgender troops against the service members who sued to stop it, the Associated Press and Military.com reported. Lawyers for the plaintiffs said 27 people are covered.

## The order

Judges Robert Wilkins and Judith Rogers voted to deny the government''''s request for a stay, and Judge Justin Walker would have granted it, according to the reports. Military.com reported that the court directed its clerk to issue the mandate immediately, and the clerk did so the same day.

In a seven-page statement, Wilkins wrote that the government had not shown it would suffer irreparable harm from keeping the plaintiffs in uniform or identified the national security risks it cited. He noted that the injunction had been narrowed to a limited group of currently serving plaintiffs. The order does not cover other transgender service members or people seeking to enlist.

## How the case got here

Trump signed an executive order in January 2025 declaring that transgender troops'''' gender identity conflicts with military service, and Defense Secretary Pete Hegseth''''s policy presumptively disqualifies people with gender dysphoria, AP reported. The Supreme Court allowed the policy to be enforced in May 2025 in a separate case. U.S. District Judge Ana Reyes blocked it for the plaintiffs in this case in March 2025, and the appeals panel upheld that ruling in June 2026 over Walker''''s dissent.

The Justice Department has asked the Supreme Court to review the June decision, and the justices are scheduled to consider the request at their conference on Friday, Dec. 4, according to Military.com. A two-week trial before Reyes is set to begin on Jan. 4. Shannon Minter, legal director of the National Center for LGBTQ Rights, welcomed the order.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/E._Barrett_Prettyman_U.S._Courthouse.JPG/1280px-E._Barrett_Prettyman_U.S._Courthouse.JPG', 'The E. Barrett Prettyman U.S. Courthouse in Washington (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-20.sql', 7, 0, 'newsroom-assistant', '2026-11-20T11:00:00.000Z', '2026-11-20T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261120-dc-circuit-transgender-troops-src1', 'bd-20261120-dc-circuit-transgender-troops', 'Divided appeals court blocks Pentagon from expelling several transgender troops from US military', 'https://abcnews.com/US/wireStory/divided-appeals-court-blocks-pentagon-expelling-transgender-troops-138228654', 'Associated Press (via ABC News)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-20T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-20. Editor to confirm.', 'newsroom-assistant', '2026-11-20T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261120-dc-circuit-transgender-troops-src2', 'bd-20261120-dc-circuit-transgender-troops', 'Court Blocks Pentagon From Discharging 27 Transgender Troops Under Trump-Hegseth Policy', 'https://www.military.com/court-blocks-pentagon-from-discharging-27-transgender-troops-under-trump-hegseth-policy', 'Military.com', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-20T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-20. Editor to confirm.', 'newsroom-assistant', '2026-11-20T11:00:00.000Z');
