INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261120-texans-colts', 'texans-26-colts-3-stroud-three-touchdowns-anderson-safety-thursday-night-football', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Texans 26, Colts 3: C.J. Stroud throws three touchdown passes as Houston holds Indianapolis to 167 yards (Thu., Nov. 19)', 'Will Anderson Jr. sacked Daniel Jones for a safety and David Montgomery ran for 107 yards in his return. The Texans won at home for the first time this season.', 'The Houston Texans beat the Indianapolis Colts 26-3 in Houston on Thursday, Nov. 19, in the week''''s Thursday night game, according to ESPN''''s recap and NBC''''s game report.

## How it went

Indianapolis took a 3-0 lead on Spencer Shrader''''s 34-yard field goal on the opening drive, and never scored again. C.J. Stroud answered with a 42-yard touchdown pass to Nico Collins late in the first quarter, and Kayshon Boutte caught a 24-yard touchdown pass to finish an 85-yard drive in the second. Houston led 17-3 at halftime, ESPN''''s line score shows.

In the third quarter, Will Anderson Jr. sacked Colts quarterback Daniel Jones in the end zone for a safety, and Stroud found rookie Marlin Klein for a 13-yard touchdown on the next possession.

## The numbers

Stroud completed 21 of 27 passes for 194 yards with three touchdowns and one interception. David Montgomery, back from a four-game absence with a groin injury, ran 26 times for a season-high 107 yards. Jones completed 12 of 27 passes for 144 yards with an interception before Anthony Richardson replaced him late, and Jonathan Taylor was held to 21 yards on 11 carries.

The Colts finished with 167 total yards, a season low, and failed to score a touchdown for the first time since November 2024, ESPN reported. Colts coach Shane Steichen said "we''''ll evaluate everything" when asked about his starting quarterback.

## Where it leaves them

The Texans are 4-6, and the Colts are 3-8 after their sixth loss in seven games. Texans defensive end Chris Braswell was carted off with a knee injury after the opening kickoff. Both teams play again on Sunday, Nov. 29: Houston hosts Baltimore, and Indianapolis hosts the New York Giants.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/NRG_Stadium_before_Super_Bowl_LI.jpg/1280px-NRG_Stadium_before_Super_Bowl_LI.jpg', 'NRG Stadium in Houston, home of the Texans (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-20.sql', 7, 0, 'newsroom-assistant', '2026-11-20T11:00:00.000Z', '2026-11-20T11:00:00.000Z');
