INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261120-patriots-devito-morton-plan', 'patriots-plan-tommy-devito-behren-morton-drake-maye-ankle-injury-report', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Patriots plan to stay with Tommy DeVito and Behren Morton at quarterback while Drake Maye is out, report says', 'MassLive reported on Thursday, Nov. 19, that New England is not adding a veteran for now. Coach Mike Vrabel has said he does not expect Maye back right after the bye.', 'The Patriots plan to go forward with Tommy DeVito as their starting quarterback and rookie Behren Morton as his backup for now, MassLive''''s Mark Daniels reported on Thursday, Nov. 19, citing a league source, according to Patriots Wire. The report said New England is not planning to bring in a veteran at this point.

## Why DeVito

The Patriots signed DeVito to a two-year deal worth up to $7.4 million in the offseason and released Joshua Dobbs, Patriots Wire noted. Filling in for Drake Maye against Detroit in Germany on Sunday, Nov. 15, DeVito completed 12 of 24 passes for 81 yards with one touchdown and one interception. Morton is a rookie draft pick.

Earlier in the week, insider Jordan Schultz reported that the Patriots would explore the quarterback market during their bye, Pro Football Rumors reported. Coach Mike Vrabel said he did not see an addition happening right then, according to the Boston Herald''''s Doug Kyed.

## Maye''''s injury

Maye was hurt on the Patriots'''' first drive against the Lions when Aidan Hutchinson rolled onto his right ankle, NESN reported. ESPN''''s Adam Schefter reported that the team feared a fractured ankle that could require surgery and that Maye stayed in Germany for more tests. Vrabel said he did not imagine Maye being available coming out of the bye. NESN reported that a fracture would likely cost him most or all of the regular season.

NESN described New England as one of several teams in the mix for the final AFC wild-card spot. The Patriots return from their bye against the Los Angeles Chargers at 4:05 p.m. ET on Sunday, Nov. 29, as Boston Daily reported on Wednesday, Nov. 18.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Patriots_on_offense_at_New_England_at_Oakland_12-14-08_1.JPG/1280px-Patriots_on_offense_at_New_England_at_Oakland_12-14-08_1.JPG', 'The Patriots on offense in a 2008 game in Oakland (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-20.sql', 6, 0, 'newsroom-assistant', '2026-11-20T11:00:00.000Z', '2026-11-20T11:00:00.000Z');
