INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261120-red-sox-rutschman-castro', 'red-sox-rutschman-extension-considered-report-allan-castro-signs-yankees', 'newsroom', 'news_story', 'mlb', 'EDITORIAL_REVIEW', 0, 'Red Sox weighed a Rutschman extension when they traded for him, report says, as former prospect Allan Castro signs with the Yankees', 'No extension has been reported for the catcher, who has one year of club control left. Castro hit 15 home runs at Triple-A in 2026.', 'The Red Sox considered a contract extension for catcher Adley Rutschman when they acquired him from the Baltimore Orioles at the trade deadline, NESN reported on Thursday, Nov. 19, pointing to a Nov. 17 column by Ken Rosenthal of The Athletic.

## Where things stand

Boston sent a large package of players to Baltimore for Rutschman, who was on the injured list at the time of the deal and has one year of club control remaining, according to NESN. No extension has been reported, and no terms have surfaced. NESN noted that chief baseball officer Craig Breslow prefers to keep negotiations private, and that the club had considered how a possible lockout could cut into the 2027 season.

If no deal is reached, Rutschman would be one of the biggest names in free agency over the next year, NESN reported.

## Castro heads to New York

Separately, Allan Castro, a 23-year-old switch-hitting outfielder who had been in the Red Sox system since 2021, signed a minor league contract with the New York Yankees, according to the Yankees'''' transaction log as reported by the New York Daily News and Red Sox On SI. Castro hit .252 with 15 home runs, 77 RBI and 20 stolen bases in 119 games at Triple-A in 2026.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Adley_Rutschman_(48130140726)_(cropped).jpg/1280px-Adley_Rutschman_(48130140726)_(cropped).jpg', 'Adley Rutschman (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-20.sql', 6, 0, 'newsroom-assistant', '2026-11-20T11:00:00.000Z', '2026-11-20T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261120-red-sox-rutschman-castro-src1', 'bd-20261120-red-sox-rutschman-castro', 'Red Sox Extending Adley Rutschman Was Part of Blockbuster Deal, Per Report', 'https://sports.yahoo.com/articles/red-sox-extending-adley-rutschman-060525179.html', 'NESN (via Yahoo Sports)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-20T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-20. Editor to confirm.', 'newsroom-assistant', '2026-11-20T11:00:00.000Z');
