INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261120-harvard-yale-fenway', 'harvard-yale-the-game-142nd-fenway-park-saturday-nov-21-espnu', 'newsroom', 'news_story', 'college-football', 'EDITORIAL_REVIEW', 0, 'Harvard and Yale bring the 142nd playing of The Game to Fenway Park on Saturday, Nov. 21', 'Kickoff is set for 3:30 p.m. ET on ESPNU, with the Red Sox hosting the Ivy League rivals at their ballpark.', 'Harvard and Yale will play the 142nd edition of The Game at Fenway Park on Saturday, Nov. 21, with kickoff at 3:30 p.m. ET and a national broadcast on ESPNU, according to Harvard Athletics.

## Back at Fenway

The Red Sox list the game on Fenway''''s event schedule as The Game: Harvard-Yale 2026 and are selling a Touchdown Club package that includes a buffet from 2 to 5 p.m. and access to the park''''s 521 Overlook, according to the team''''s ticket page.

## Before you go

Fans should check the Red Sox and Harvard Athletics pages for gate times and ballpark rules before heading to Fenway.

Boston Daily will post the result after the final whistle.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Fenway_Park_2009.jpg/1280px-Fenway_Park_2009.jpg', 'Fenway Park in Boston, 2009 (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-20.sql', 6, 0, 'newsroom-assistant', '2026-11-20T11:00:00.000Z', '2026-11-20T11:00:00.000Z');
